def mse_from_terms(bias, variance, noise=0.0):
    """Return bias squared plus variance plus irreducible noise."""
    return bias + variance + noise   # BUG: the bias term is not squared

tests_py:
def test_zero_bias():
    assert solution.mse_from_terms(0.0, 4.0, 0.0) == 4.0

def test_basic():
    assert solution.mse_from_terms(2.0, 1.0, 0.5) == 5.5

def test_negative_bias():
    assert solution.mse_from_terms(-3.0, 2.0, 0.0) == 11.0

def test_noise_default():
    assert solution.mse_from_terms(1.0, 2.0) == 3.0

def test_returns_float():
    assert isinstance(solution.mse_from_terms(1, 0), float)

def test_zero_all():
    assert solution.mse_from_terms(0.0, 0.0, 0.0) == 0.0
